import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>

#define K 3
#define CIN 3
#define COUT 32

__global__ void conv2d_bf16_kernel(
    const __nv_bfloat16* __restrict__ input,
    const __nv_bfloat16* __restrict__ weight,
    __nv_bfloat16* __restrict__ output,
    int N, int H, int W, int H_out, int W_out)
{
    // Load full weight tensor into shared memory (COUT*CIN*K*K elements)
    __shared__ float s_weight[COUT * CIN * K * K];
    int wsize = COUT * CIN * K * K;
    for (int i = threadIdx.x; i < wsize; i += blockDim.x) {
        s_weight[i] = __bfloat162float(weight[i]);
    }
    __syncthreads();

    long total = (long)N * COUT * H_out * W_out;
    long idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
    long stride = (long)blockDim.x * gridDim.x;

    for (; idx < total; idx += stride) {
        long tmp = idx;
        int wo = tmp % W_out; tmp /= W_out;
        int ho = tmp % H_out; tmp /= H_out;
        int co = tmp % COUT; tmp /= COUT;
        int n = tmp;

        float sum = 0.0f;

        const __nv_bfloat16* in_base = input + ((long)n * CIN * H * W);
        const float* w_base = s_weight + co * (CIN * K * K);

        #pragma unroll
        for (int ci = 0; ci < CIN; ci++) {
            const __nv_bfloat16* in_c = in_base + (long)ci * H * W;
            const float* w_c = w_base + ci * K * K;
            #pragma unroll
            for (int kh = 0; kh < K; kh++) {
                int in_h = ho + kh;
                const __nv_bfloat16* in_row = in_c + (long)in_h * W + wo;
                const float* w_row = w_c + kh * K;
                #pragma unroll
                for (int kw = 0; kw < K; kw++) {
                    float in_val = __bfloat162float(in_row[kw]);
                    sum += in_val * w_row[kw];
                }
            }
        }

        output[idx] = __float2bfloat16(sum);
    }
}

torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kBFloat16, "input must be bfloat16");
    TORCH_CHECK(weight.dtype() == torch::kBFloat16, "weight must be bfloat16");

    input = input.contiguous();
    weight = weight.contiguous();

    int N = input.size(0);
    int C_in = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int C_out = weight.size(0);

    int H_out = H - K + 1;
    int W_out = W - K + 1;

    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());

    long total = (long)N * C_out * H_out * W_out;
    int threads = 256;
    int blocks = (int)((total + threads - 1) / threads);
    if (blocks > 65535) blocks = 65535;

    conv2d_bf16_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __nv_bfloat16*>(input.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(weight.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(output.data_ptr<at::BFloat16>()),
        N, H, W, H_out, W_out
    );

    return output;
}
"""

conv2d_cpp_source = r"""
torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight);
"""

conv2d_module = load_inline(
    name="conv2d_bf16_module",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        ref_conv = nn.Conv2d(3, 32, kernel_size=3, bias=False, dtype=torch.bfloat16)
        self.weight = nn.Parameter(ref_conv.weight.detach().clone())
        self.conv2d_module = conv2d_module
    def forward(self, x):
        return self.conv2d_module.conv2d_forward(x, self.weight)
        return self.conv2d_module.conv2d_forward(x, self.weight)

